def parse_log_file(log_file_path):
    error_patterns = {
        'ERROR': re.compile(r'ERROR|Error|error'),
        'WARNING': re.compile(r'WARNING|Warning|warning'),
        'FAULT': re.compile(r'FAULT|Fault|fault'),
    }
    fault_summary = {
        'ERROR': [],
        'WARNING': [],
        'FAULT': [],
        'UNKNOWN': []
    }

    with open(log_file_path, 'r') as file:
        for line in file:
            matched = False
            for category, pattern in error_patterns.items():
                if pattern.search(line):
                    fault_summary[category].append(line.strip())
                    matched = True
                    break
            if not matched:
                # Check for unusual patterns (e.g., repeated failures, timeouts)
                if 'timeout' in line.lower() or 'failed' in line.lower():
                    fault_summary['FAULT'].append(line.strip())
                else:
                    fault_summary['UNKNOWN'].append(line.strip())
    return fault_summary

def diagnose_faults(fault_summary):
