```javascript
// Function to send data to the server
function sendData(data) {
  fetch('/log-interactions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(data)
  }).catch(err => {
    console.error('Failed to send interaction data:', err);
  });
